BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q227', 'データベース方式とデータモデル',
   '業務システムでは、複数のアプリケーションプログラムが同じデータ(顧客情報など)を扱うことが多い。各プログラムがそれぞれ専用のファイルにデータを保持する方式と比べて、DBMS(データベース管理システム)を導入する利点として最も適切なものはどれか。',
   NULL::text,
   '["データを一箇所にまとめて複数のプログラムから共有できるようにし、更新の手間や内容の食い違いを防ぐこと。", "各プログラムが扱うデータの量が増えても、検索や更新にかかる処理速度が常に一定のまま変わらないようにすること。", "ネットワークを経由せずに、遠く離れた拠点からでもデータを直接読み書きできるようにすること。", "アプリケーションのソースコード全体を暗号化し、第三者に解析されないようにすること。"]',
   0,
   '[0]',
   'single',
   '{"asked": "各プログラムが個別にファイルを持つ方式と比べて、DBMSを導入する利点を問う設問。", "point": "同じデータをあちこちに重複して持たず、一箇所で管理して複数プログラムに共有させるのがDBMSの役割。", "kid": "DBMSは、みんなが使う共通のデータを1か所にまとめて管理してくれる仕組み。", "eg": "たとえると、各部署がそれぞれ別の紙の顧客名簿を持つのではなく、1冊の共通の名簿を全部署が見に行く方式に変えるようなもの。", "terms": [["DBMS", "データベース管理システム。データの保存・検索・更新を一括して引き受けるソフトウェア"], ["ファイル処理方式", "各プログラムが専用のファイルに個別にデータを持つ、DBMSを使わない古い方式"]], "think": "なぜDBMSを介するのかがカギ。各業務プログラムが個別にファイルを持つと、同じ『顧客の住所』のような情報があちこちに重複して存在する。住所が変わったとき、1か所を直し忘れると、プログラムによって表示される住所が違うという矛盾が生じる。DBMSはデータを一元的に管理し、どのプログラムも同じデータを参照する形にするので、更新は1箇所で済み、矛盾も起きにくくなる。だからアプリが直接ファイルを読み書きせず、DBMSを介する。", "vs": "実行速度が常に一定になる、ネットワーク無しで遠隔地から直接読み書きできる、ソースコードを暗号化するといった話は、DBMSが果たす一元管理の役割とは別の話であり、DBMS導入の一般的な利点として説明されるものではない。", "why_asked": "DBMSの存在意義を『何をしてくれるか』ではなく『なぜ必要か』のレベルで理解しているかを問う定番の切り口。", "opt": ["正解。データを一元管理し複数プログラムで共有することで、更新の手間と矛盾の発生を減らせる。", "データ量が増えれば検索や更新にかかる処理量も増えるのが通常であり、常に一定というのは誤り。", "DBMSはデータの一元管理を担う仕組みであり、ネットワークを介さない遠隔アクセスを実現する機能ではない。", "DBMSの主目的はデータの一元管理・共有であり、ソースコードの暗号化は別の話である。"]}'),

  ('ap-core-q228', 'データベース方式とデータモデル',
   'DBMSが持つ機能は、大きく「データの入れ物の形を決める機能」「データを検索・追加・更新する機能」「誰がどこまで触ってよいかを管理する機能」の3つに分けて整理されることが多い。このうち、特定の利用者やプログラムに対して、扱えるテーブルや列の範囲を制限するなど、データへのアクセスを管理する機能を一般に何と呼ぶか。',
   NULL::text,
   '["データ制御機能", "データ定義機能", "データ操作機能", "データ変換機能"]',
   0,
   '[0]',
   'single',
   '{"asked": "DBMSの機能分類のうち、アクセス範囲を管理する機能の名称を問う設問。", "point": "『誰が・どこまで触ってよいか』を管理する機能がデータ制御機能。定義(入れ物の形)・操作(検索や更新)とは別枠。", "kid": "DBMSの仕事は『入れ物の形を決める』『中身を操作する』『触ってよい範囲を決める』の3つに分けて考えられる。", "eg": "たとえると、図書館の仕事を『本棚の仕切り方を決める』『本を借りる・返す』『閲覧室に入れる人を制限する』の3つに分けて考えるようなもの。", "terms": [["データ定義機能", "テーブルや列といったデータの入れ物の形を決める機能"], ["データ操作機能", "検索・追加・更新・削除などデータそのものを操作する機能"]], "think": "なぜDBMSの機能をこの3つに分けて考えるのかがカギ。DBMSがやることを整理すると、①データの入れ物(テーブル)の形を決める働き、②中身を検索・追加・更新する働き、③誰がどこまで触ってよいかを決める働きの3つに分けられる。特定の利用者には特定のテーブルや列だけを見せ、それ以外は見せないというアクセス範囲の管理は、③にあたる働きであり、これをデータ制御機能と呼ぶ。", "vs": "データ定義機能はテーブルの構造そのものを決める働き、データ操作機能は検索・追加・更新といった中身の操作を行う働きであり、どちらもアクセス範囲を制限する働きそのものではない。", "why_asked": "DBMSの機能を『定義・操作・制御』という3分類で整理できているかを問う定番の切り口。", "opt": ["正解。誰がどこまでデータに触れるかを管理する働きはデータ制御機能にあたる。", "データ定義機能はテーブルや列といった入れ物の形を決める働きであり、アクセス範囲の管理とは別。", "データ操作機能は検索・追加・更新など中身を操作する働きであり、アクセス範囲の管理とは別。", "データ変換機能という名称は、DBMSの基本機能の分類としては一般的でない。"]}'),

  ('ap-core-q229', 'データベース方式とデータモデル',
   'データベースのモデル(データの表現方式)のうち、データとデータの関係を木のような親子関係で表し、1つの子要素は必ず1つの親要素にしか属せないという制約を持つものはどれか。',
   NULL::text,
   '["階層型データベース", "ネットワーク型データベース", "リレーショナル型データベース", "オブジェクト指向データベース"]',
   0,
   '[0]',
   'single',
   '{"asked": "木構造で親子関係を表し、子は1つの親にしか属せないというデータベースモデルの名称を問う設問。", "point": "『1つの子は1つの親だけ』という木構造の制約を持つのが階層型データベース。", "kid": "階層型は、組織図や家系図のように、上から下へ枝分かれする木の形でデータを表すモデル。", "eg": "たとえると、会社の組織図。1人の社員は必ず1つの部署の下にぶら下がり、同時に2つの部署に正式所属する、という書き方はできない。", "terms": [["階層型データベース", "データを木構造(親子関係)で表すデータベースモデル"], ["ネットワーク型データベース", "子要素が複数の親要素を持てるよう、木構造の制約を緩めたモデル"]], "think": "なぜ階層型は『1つの子に1つの親』なのかがカギ。階層型は組織図や家系図のように、上位から下位へ一本道でたどれる木構造でデータを表す。木構造には、ある枝から別の枝へ直接移る道が無いため、1つの子要素が複数の親要素にまたがって属することを表現できない。たとえば『1つの部品が2つの製品に共通して使われる』ような関係は、木構造のままでは1か所にしか置けず、無理に表そうとすると同じデータを重複して持つ必要が出てくる。この制約を緩和する動機から、後にネットワーク型が生まれた。", "vs": "ネットワーク型は1つの子要素が複数の親要素を持てるよう制約を緩めたモデル、リレーショナル型は木構造ではなく行と列を持つ表でデータを表すモデルであり、いずれも『子は1つの親だけ』という制約そのものではない。", "why_asked": "階層型・ネットワーク型・リレーショナル型という3つの伝統的なデータベースモデルの特徴を見分けられるかを問う定番の切り口。", "opt": ["正解。木構造で親子関係を表し、子は1つの親にしか属せない制約を持つのは階層型データベースである。", "ネットワーク型は、階層型の制約を緩め、1つの子要素が複数の親要素を持てるようにしたモデルである。", "リレーショナル型は、木構造ではなく行と列を持つ表(関係)でデータを表すモデルである。", "オブジェクト指向データベースは、データと処理をひとまとめにしたオブジェクトとしてデータを表すモデルである。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"140\" y=\"15\" width=\"60\" height=\"30\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"170\" y=\"34\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">親</text><line x1=\"150\" y1=\"45\" x2=\"90\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><line x1=\"190\" y1=\"45\" x2=\"250\" y2=\"70\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><rect x=\"60\" y=\"70\" width=\"60\" height=\"30\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"90\" y=\"89\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">子1</text><rect x=\"220\" y=\"70\" width=\"60\" height=\"30\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"250\" y=\"89\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">子2</text><text x=\"170\" y=\"125\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\">1つの子は必ず1つの親にしかつながらない</text></svg>"}'),

  ('ap-core-q230', 'データベース方式とデータモデル',
   'データベースのモデルのうち、階層型の「1つの子要素は1つの親要素にしか属せない」という制約を緩め、1つの子要素が複数の親要素とのつながりを持てるようにしたモデルはどれか。',
   NULL::text,
   '["ネットワーク型データベース", "階層型データベース", "リレーショナル型データベース", "キーバリュー型データベース"]',
   0,
   '[0]',
   'single',
   '{"asked": "階層型の制約を緩め、子要素が複数の親要素を持てるようにしたデータベースモデルの名称を問う設問。", "point": "子要素が複数の親要素とつながれる、網の目のような構造を持つのがネットワーク型データベース。", "kid": "ネットワーク型は、階層型の『子は1つの親だけ』という制約をなくし、データ同士を網の目のように自由につなげられるようにしたモデル。", "eg": "たとえると、階層型が『上司は1人だけ』の組織図だとすれば、ネットワーク型は複数のプロジェクトを掛け持ちし、複数の上司から指示を受けるような、糸が縦横に張り巡らされた関係図。", "terms": [["ネットワーク型データベース", "子要素が複数の親要素とのつながりを持てる、網の目状の構造を持つデータベースモデル"], ["ポインタ", "あるデータから別のデータへのつながりを指し示す情報。ネットワーク型ではこれをたどってデータを探す"]], "think": "なぜ複数の親を持てるように拡張したのかがカギ。階層型は木構造の制約のため『1つの部品が複数の製品に使われる』のような関係を素直に表せなかった。ネットワーク型は、データ同士を網の目(グラフ)のように自由につなげられるようにし、1つの子要素が複数の親要素へのつながりを持てるようにした。これにより表現力は上がったが、つながりをたどる経路をプログラム側が意識してたどる必要があり、扱いが複雑になるという代償もあった。", "vs": "階層型は子要素が1つの親要素にしか属せない木構造のモデル、リレーショナル型は行と列を持つ表でデータを表すモデルであり、いずれも複数の親要素とのつながりを許すネットワーク型の特徴とは異なる。", "why_asked": "階層型からネットワーク型への発展の動機(表現力の拡張とその代償)を理解しているかを問う切り口。", "opt": ["正解。子要素が複数の親要素とのつながりを持てる、網の目状の構造を持つのはネットワーク型データベースである。", "階層型は、子要素が1つの親要素にしか属せないという制約を持つ木構造のモデルである。", "リレーショナル型は、行と列を持つ表(関係)でデータを表すモデルであり、木や網の目の構造そのものではない。", "キーバリュー型は、キーと値の組でデータを保持する比較的新しいモデルであり、伝統的な階層型・ネットワーク型・リレーショナル型の分類とは別の系統である。"]}'),

  ('ap-core-q231', 'データベース方式とデータモデル',
   '階層型やネットワーク型に比べて、リレーショナル型データベースが現在広く使われるようになった理由として最も適切なものはどれか。',
   NULL::text,
   '["データを行と列を持つ表という単純な形式で表し、経路を意識せずSQLという共通の言語で操作できるから。", "階層型やネットワーク型よりも、動作に必要とするハードウェアの記憶容量が常に少なくて済むから。", "1つの子要素が複数の親要素を持てるという表現力の高さが、階層型やネットワーク型よりも優れているから。", "扱うプログラム言語の種類を問わず、同じソースコードがそのまま動作するようになるから。"]',
   0,
   '[0]',
   'single',
   '{"asked": "リレーショナル型データベースが主流になった理由を問う設問。", "point": "経路をたどらず『行を絞る・列を絞る・表をつなぐ』という演算で欲しい結果を宣言できる単純さが、主流になった理由。", "kid": "リレーショナル型は、データを誰でもわかる『表』の形で表し、SQLという共通の言葉で操作できるので広まった。", "eg": "たとえると、階層型・ネットワーク型は路線図を頭に入れて乗り換えを自分でたどる乗り方、リレーショナル型は行き先だけ告げればあとはお任せのタクシーのようなもの。", "terms": [["SQL", "リレーショナル型データベースを操作するための共通の言語"], ["関係代数", "表に対する演算(選択・射影・結合など)としてデータ操作を捉える理論。SQLの土台になっている考え方"]], "think": "なぜ表という単純な形式が勝ち残ったのかがカギ。階層型・ネットワーク型は、データ同士のつながりを木や網の目としてあらかじめ組み上げておき、取り出すときもその経路(どの親からどの子へたどるか)をプログラム側が意識して指定する必要があった。リレーショナル型は、データを行と列という誰でも理解できる表の形式だけで表し、経路をたどる代わりに『条件に合う行を選ぶ』『必要な列だけ取り出す』『共通の値で表同士をつなげる』という演算(SQL)で欲しい結果を宣言するだけでよい。経路を意識しなくてよいぶん設計・変更・学習のコストが下がり、業務システムの主流になった。", "vs": "『1つの子要素が複数の親要素を持てる』という表現力の高さはネットワーク型の特徴であり、リレーショナル型が主流になった理由(経路を意識しない単純さ)とは逆方向の話である。", "why_asked": "単なる用語の暗記ではなく、リレーショナル型が広まった技術的な理由(経路を意識しない操作性)を理解しているかを問う切り口。", "opt": ["正解。経路をたどらず、表という単純な形式とSQLという共通の言語で操作できることが、リレーショナル型が主流になった理由である。", "記憶容量の必要量は、モデルの種類ではなくデータ量や設計に左右されるものであり、主流になった理由として一般的に説明される点ではない。", "複数の親要素を持てる表現力の高さはネットワーク型の特徴であり、単純さで広まったリレーショナル型の説明としては逆である。", "SQLはリレーショナル型データベースを操作するための言語であり、あらゆるプログラム言語のソースコードがそのまま動作するという話ではない。"]}'),

  ('ap-core-q232', 'データベース方式とデータモデル',
   'データベースモデルに関する記述のうち、最も適切なものはどれか。',
   NULL::text,
   '["リレーショナル型データベースでは、データを行と列を持つ表(関係)として表し、複数の表を共通の値で結びつけて扱う。", "階層型データベースでは、データ同士のつながりを行と列を持つ表として表し、SQLという言語を使って検索や更新を行う。", "ネットワーク型データベースでは、1つの子要素は必ずただ1つの親要素にしかつながりを持てないという制約がある。", "階層型・ネットワーク型・リレーショナル型は、いずれもデータを木構造で表し、親子関係のたどり方だけが異なる。"]',
   0,
   '[0]',
   'single',
   '{"asked": "階層型・ネットワーク型・リレーショナル型それぞれの特徴を正しく説明した記述を選ぶ設問。", "point": "表(行と列)で表しSQLで操作するのはリレーショナル型だけ。他の2モデルの説明とすり替わっていないか確認する。", "kid": "3つのモデルにはそれぞれ別々の特徴があり、名前と特徴の組み合わせを取り違えないことが大切。", "eg": "たとえると、3人の似た経歴の候補者のプロフィールを見比べ、どの実績が誰のものかを取り違えずに言い当てるようなもの。特徴自体は正しくても、結びつける相手を間違えると誤りになる。", "terms": [["関係(リレーション)", "リレーショナル型データベースで、行と列を持つ表そのものを指す用語"]], "think": "なぜこの手の問題で間違えやすいのかがカギ。階層型・ネットワーク型・リレーショナル型は、それぞれ単体の特徴を覚えていても、選択肢の中で名前と特徴の組み合わせを入れ替えられると見抜けないことが多い。表(行と列)で表しSQLで操作するという特徴はリレーショナル型だけのものであり、子要素が1つの親要素にしか属せないという制約は階層型だけのものである。それぞれの特徴を『この特徴はどのモデル固有か』まで結びつけて覚えていないと、入れ替えられた記述に気づけない。", "why_asked": "3つのモデルの特徴を混同せずに区別できているかを、記述の正誤判定という形で総合的に問う切り口。", "opt": ["正解。リレーショナル型は行と列を持つ表でデータを表し、複数の表を共通の値で結びつけて扱う。", "行と列を持つ表で表しSQLで操作するのはリレーショナル型の特徴であり、階層型の説明として誤り。", "1つの子要素が1つの親要素にしか属せないのは階層型の制約であり、ネットワーク型はこの制約を緩めたモデルなので誤り。", "リレーショナル型は木構造ではなく表でデータを表すモデルであり、3モデルすべてが木構造という説明は誤り。"]}'),

  ('ap-core-q233', 'データベース方式とデータモデル',
   '関係代数(表に対する基本的な演算の体系)における「選択」の説明として最も適切なものはどれか。',
   NULL::text,
   '["表の中から、指定した条件に合う行だけを取り出す演算。", "表の中から、指定した列だけを取り出す演算。", "複数の表を、共通する値をもとに1つの表につなぎ合わせる演算。", "表の行の並び順を、指定した列の値に従って並べ替える演算。"]',
   0,
   '[0]',
   'single',
   '{"asked": "関係代数における『選択』が何を行う演算かを問う設問。", "point": "選択は行を絞る演算。SQLのWHERE句に対応する考え方。", "kid": "選択は、表の中から条件に合う行だけを残す演算。", "eg": "たとえると、名簿(表)から『東京都在住の人』という条件で、当てはまる人(行)だけを付箋で残し、それ以外を除くようなもの。", "terms": [["関係代数", "表(リレーション)を対象にした演算の体系。SQLの考え方の土台になっている"], ["行", "表の中の1件分のデータのまとまり(レコード)"]], "think": "なぜ『選択』が行を絞る演算と呼ばれるのかがカギ。関係代数は表を対象にした演算の体系で、SQLのSELECT文の元になっている考え方。このうち選択は、表の中の各行を条件に照らし、条件を満たす行だけを残し、満たさない行を捨てる演算。SQLでいえばWHERE句に対応する考え方にあたる。", "vs": "選択は行を絞り、射影は列を絞る。どちらも表を絞り込む点は同じだが、絞る対象(行か列か)が逆であることに注意。結合は複数の表をつなぐ演算であり、1つの表を絞り込む選択とは対象が異なる。", "why_asked": "関係代数の基本三演算(選択・射影・結合)を、名前と働きの組み合わせで正しく見分けられるかを問う定番の切り口。", "opt": ["正解。表の中から条件に合う行だけを取り出す演算が選択である。", "指定した列だけを取り出す演算は射影の説明であり、選択の説明ではない。", "複数の表を共通する値でつなぎ合わせる演算は結合の説明であり、選択の説明ではない。", "行の並べ替えは、選択・射影・結合という関係代数の基本演算には含まれない操作である。"]}'),

  ('ap-core-q234', 'データベース方式とデータモデル',
   '関係代数における「射影」の説明として最も適切なものはどれか。',
   NULL::text,
   '["表の中から指定した列だけを取り出し、他の列を除いた表を作る演算。", "表の中から、指定した条件に合う行だけを選んで取り出していく演算。", "複数の表を、共通する値をもとにして1つの表につなぎ合わせていく演算。", "表の中にある指定した列の値を、別の値に一括して置き換えていく演算。"]',
   0,
   '[0]',
   'single',
   '{"asked": "関係代数における『射影』が何を行う演算かを問う設問。", "point": "射影は列を絞る演算。SQLでどの列を取得するかを指定する部分に対応する考え方。", "kid": "射影は、表の中から必要な列だけを取り出し、それ以外の列は除く演算。", "eg": "たとえると、名簿(表)から『氏名』と『メールアドレス』の列だけを紙に書き写し、住所や電話番号の列は書き写さないようにするようなもの。", "terms": [["列", "表の中の項目(氏名・住所など)の並び(フィールド)"]], "think": "なぜ『射影』が列を絞る演算と呼ばれるのかがカギ。射影は、表の各行はそのまま残しつつ、列だけを間引いて、指定した列だけの表を作る演算。SQLでいえばSELECT文でどの列を取得するかを指定する部分に対応する考え方。", "vs": "射影は列を絞り、選択は行を絞る。名前は似ているが働きは逆である。列の値そのものを別の値に置き換える操作は、関係代数の基本演算である射影とは別の話である。", "why_asked": "選択(行を絞る)と射影(列を絞る)を取り違えていないかを問う定番の切り口。", "opt": ["正解。指定した列だけを取り出し、それ以外の列を除いた表を作る演算が射影である。", "指定した条件に合う行だけを取り出す演算は選択の説明であり、射影の説明ではない。", "複数の表を共通する値でつなぎ合わせる演算は結合の説明であり、射影の説明ではない。", "列の値を別の値に一括して置き換える操作は、関係代数の基本演算である射影の定義には含まれない。"]}'),

  ('ap-core-q235', 'データベース方式とデータモデル',
   '関係代数における「結合」の説明として最も適切なものはどれか。',
   NULL::text,
   '["複数の表を、共通する値(キー)をもとに、1つの表につなぎ合わせる演算。", "1つの表の中から、指定した条件に合う行だけを選んで取り出していく演算。", "1つの表の中から、指定した列だけを取り出していき、残りの列は除く演算。", "複数の表の内容を、単純に上下へつなげて1つの表にまとめていく演算。"]',
   0,
   '[0]',
   'single',
   '{"asked": "関係代数における『結合』が何を行う演算かを問う設問。", "point": "結合は共通の値で複数の表を横につなぐ演算。SQLのJOINに対応する考え方。", "kid": "結合は、別々の表を、共通する値を手がかりにつなぎ合わせて1つの表にする演算。", "eg": "たとえると、『注文一覧』と『顧客名簿』という別々の紙を、顧客番号を手がかりにホチキスで綴じ合わせ、注文ごとに顧客名も見える1枚の表を作るようなもの。", "terms": [["キー", "表同士をつなぐ手がかりになる、共通して持つ値(顧客番号など)"], ["JOIN", "SQLで結合に対応する操作を行う構文"]], "think": "なぜ『結合』は表と表をつなぐ演算なのかがカギ。実務のデータは『注文』表と『顧客』表のように複数の表に分けて持つことが多い。結合は、両方の表に共通して存在する値(例えば顧客番号)を手がかりに、対応する行同士を横につなぎ合わせ、1つの表にまとめる演算。SQLでいえばJOINに対応する考え方。単純に表を上下に積み重ねるだけの演算とは異なり、共通の値で行と行を対応づける点が結合の特徴。", "vs": "結合は複数の表を横につなげる(列が増える)演算であり、表を単純に上下に積む(行が増える)演算とは異なる。1つの表から行や列を絞り込む選択・射影とも対象が異なる。", "why_asked": "結合が『表を上下に積む』操作や『1つの表を絞り込む』操作と混同されやすい点を問う切り口。", "opt": ["正解。共通する値をもとに複数の表をつなぎ合わせる演算が結合である。", "1つの表から条件に合う行だけを取り出す演算は選択の説明であり、結合の説明ではない。", "1つの表から指定した列だけを取り出す演算は射影の説明であり、結合の説明ではない。", "表を単純に上下につなげる演算は和などの集合演算にあたり、共通の値で横につなぐ結合とは異なる演算である。"]}'),

  ('ap-core-q236', 'データベース方式とデータモデル',
   '関係代数の基本的な演算である「選択」「射影」「結合」の組み合わせとして、それぞれの説明が正しく対応しているものはどれか。',
   NULL::text,
   '["選択=条件に合う行を絞る、射影=指定した列を絞る、結合=共通の値で複数の表をつなぐ。", "選択=指定した列を絞る、射影=条件に合う行を絞る、結合=共通の値で複数の表をつなぐ。", "選択=条件に合う行を絞る、射影=共通の値で複数の表をつなぐ、結合=指定した列を絞る。", "選択=表同士を上下につなげる、射影=指定した列を絞る、結合=条件に合う行を絞る。"]',
   0,
   '[0]',
   'single',
   '{"asked": "選択・射影・結合という3つの関係代数の演算と、それぞれの働きの組み合わせが正しいものを選ぶ設問。", "point": "選択=行を絞る、射影=列を絞る、結合=表をつなぐ。この3つの対応をセットで覚える。", "kid": "表に対する3つの基本的な演算を、それぞれの働きと正しく結びつけられるかを問う設問。", "eg": "たとえると、表という布地に対して『行を切り取るはさみ(選択)』『列を切り取るはさみ(射影)』『別の布をつなぐ糊(結合)』という3種類の道具を使い分けるようなもの。", "terms": [["選択", "条件に合う行を絞り出す演算"], ["射影", "指定した列を絞り出す演算"], ["結合", "共通の値で複数の表をつなぐ演算"]], "think": "なぜこの3つをセットで区別する必要があるのかがカギ。選択・射影・結合はいずれも『表から欲しい形を取り出す』演算だが、絞る対象が違う。選択は行、射影は列という、1つの表の中で絞る対象を変える演算であり、結合はそもそも複数の表をまたいでつなぎ合わせる演算という点で他の2つと性質が異なる。この3つの違いを取り違えると、SQLのWHERE・SELECTの列指定・JOINの対応関係も混同しやすくなる。", "vs": "選択と射影は『行を絞るか列を絞るか』が逆であり、最も混同されやすい組み合わせ。結合は複数の表をまたぐ点で、1つの表の中で完結する選択・射影とは根本的に性質が異なる。", "why_asked": "関係代数の3演算をまとめて識別できるかを、単発の用語問題ではなく組み合わせ問題として総合的に問う切り口。", "opt": ["正解。選択=行を絞る、射影=列を絞る、結合=表をつなぐ、という対応がそれぞれ正しい。", "選択と射影の働きが入れ替わっている。選択は行を絞る演算、射影は列を絞る演算である。", "射影と結合の働きが入れ替わっている。射影は列を絞る演算、結合は表をつなぐ演算である。", "選択の説明が表を上下につなげる操作(和などの集合演算)にすり替わっており、結合の説明も選択の働きにすり替わっている。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"55\" y=\"14\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\">選択</text><rect x=\"15\" y=\"20\" width=\"80\" height=\"18\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"15\" y=\"38\" width=\"80\" height=\"18\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><rect x=\"15\" y=\"56\" width=\"80\" height=\"18\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><text x=\"55\" y=\"90\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">条件に合う</text><text x=\"55\" y=\"102\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">行を残す</text><text x=\"170\" y=\"14\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\">射影</text><rect x=\"130\" y=\"20\" width=\"35\" height=\"54\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><rect x=\"165\" y=\"20\" width=\"35\" height=\"54\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><text x=\"170\" y=\"90\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">必要な</text><text x=\"170\" y=\"102\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">列を残す</text><text x=\"280\" y=\"14\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\">結合</text><rect x=\"240\" y=\"20\" width=\"35\" height=\"54\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><rect x=\"285\" y=\"20\" width=\"35\" height=\"54\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"275\" y1=\"47\" x2=\"285\" y2=\"47\" stroke=\"#c9a04a\" stroke-width=\"2\"/><text x=\"280\" y=\"90\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">共通の値で</text><text x=\"280\" y=\"102\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">表をつなぐ</text><text x=\"170\" y=\"130\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">選択=行を絞る／射影=列を絞る／結合=表をつなぐ</text></svg>"}'),

  ('ap-core-q237', 'データベース方式とデータモデル',
   'データベースの概念設計の段階で、扱う対象を「実体(エンティティ)」と、実体同士の「関連(リレーションシップ)」として図に表す手法を何というか。',
   NULL::text,
   '["E-R図", "フローチャート", "DFD(データフローダイアグラム)", "状態遷移図"]',
   0,
   '[0]',
   'single',
   '{"asked": "実体と関連を図で表す概念設計の手法の名称を問う設問。", "point": "『もの(実体)』と『つながり方(関連)』を四角とひし形で図に表す概念設計の手法がE-R図。", "kid": "E-R図は、扱いたい対象(顧客や商品など)と、それらの結びつき方を、先に図で整理する手法。", "eg": "たとえると、家を建てる前に、どの部屋(実体)がどの部屋とどうつながっているか(関連)を先に間取り図で描いておくようなもの。", "terms": [["実体(エンティティ)", "顧客・商品・注文のように、管理したい対象そのもの"], ["関連(リレーションシップ)", "『顧客が注文する』のような、実体同士の結びつき方"]], "think": "なぜE-R図で『実体』と『関連』を先に洗い出すのかがカギ。データベースをいきなり表(テーブル)の形で設計すると、後から『この情報とあの情報はどう結びついているか』を洗い出すのに苦労する。そこでE-R図では、まず顧客・商品・注文のような、管理したい対象そのものを実体として洗い出し、次に『顧客が注文する』『注文が商品を含む』のような実体同士のつながりを関連として整理する。人間にとって理解しやすい形で全体像を先に固めてから、テーブルの列や主キーといった具体的な設計に進むことで、設計の手戻りを減らせる。", "vs": "フローチャートは処理の手順の流れを表す図、DFDはデータの流れを表す図、状態遷移図は状態の移り変わりを表す図であり、いずれも実体と実体同士の関連という静的な構造を表す図ではない。", "why_asked": "概念設計の手法(E-R図)と、他の目的で使われる図(フローチャート・DFD・状態遷移図)を混同していないかを問う切り口。", "opt": ["正解。実体と実体同士の関連を図で表す概念設計の手法はE-R図である。", "フローチャートは処理の手順の流れを表す図であり、実体と関連を表す図ではない。", "DFDはデータがどこからどこへ流れるかを表す図であり、実体同士の関連を表す図とは視点が異なる。", "状態遷移図はある対象の状態が何によってどう移り変わるかを表す図であり、実体と関連を表す図ではない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"70\" y=\"30\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">実体</text><text x=\"270\" y=\"30\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">実体</text><rect x=\"30\" y=\"55\" width=\"80\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"70\" y=\"79\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">顧客</text><rect x=\"230\" y=\"55\" width=\"80\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"270\" y=\"79\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">注文</text><line x1=\"110\" y1=\"75\" x2=\"145\" y2=\"75\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><line x1=\"195\" y1=\"75\" x2=\"230\" y2=\"75\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><polygon points=\"170,55 195,75 170,95 145,75\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"170\" y=\"79\" font-size=\"9\" fill=\"#c9a04a\" text-anchor=\"middle\">注文する</text><text x=\"170\" y=\"120\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">四角=実体（もの）、ひし形=関連（つながり方）</text></svg>"}'),

  ('ap-core-q238', 'データベース方式とデータモデル',
   'データベースにおいて、実際に管理したいデータ(顧客名や注文日など)そのものではなく、「どのテーブルにどんな列があるか」「各列はどんな型か」といった、データの構造や意味を表す情報を何というか。',
   NULL::text,
   '["メタデータ", "トランザクションデータ", "バックアップデータ", "キャッシュデータ"]',
   0,
   '[0]',
   'single',
   '{"asked": "データの構造や意味を表す『データについてのデータ』の名称を問う設問。", "point": "データそのものではなく『データについての情報(構造・型など)』を指す言葉がメタデータ。", "kid": "メタデータは、データの中身ではなく『どんなテーブルにどんな列があるか』を記した説明書のようなもの。", "eg": "たとえると、図書館の本(実際のデータ)そのものではなく、『どの棚にどんなジャンルの本が何冊あるか』を記した蔵書目録(メタデータ)のようなもの。", "terms": [["メタデータ", "データについてのデータ。テーブルや列の構造・型などを表す情報"], ["データ辞書", "メタデータをまとめて管理する、DBMS内のカタログ"]], "think": "なぜメタデータが必要なのかがカギ。DBMSは『顧客テーブルには氏名・住所という列があり、氏名は文字列、住所も文字列』といった、データそのものではなく『データについての情報』を、データ辞書という形で別に持っている。この情報があるおかげで、DBMSは新しく届いたSQL文を読んだときに、指定された表や列が実在するか、型が合っているかを確認でき、利用者もどんなデータが格納されているかを調べられる。データの中身(実データ)とその説明書(メタデータ)を分けて管理することで、データの構造を安全に把握・変更できる。", "vs": "トランザクションデータは顧客名や注文日など実際に発生する業務データそのものであり、データの構造を表すメタデータとは指すものが逆である。バックアップデータやキャッシュデータも、実データを複製・一時保持したものであり、データの構造や意味を表す情報ではない。", "why_asked": "『データ』と『データについてのデータ(メタデータ)』を区別できているかを問う切り口。", "opt": ["正解。テーブルや列の構造・型といった、データについての情報を指すのはメタデータである。", "トランザクションデータは顧客名や注文日など実際の業務データそのものを指し、データの構造を表す情報ではない。", "バックアップデータは障害に備えて複製・保管しておく実データであり、データの構造を表す情報ではない。", "キャッシュデータは処理速度を上げるために一時的に保持する実データであり、データの構造を表す情報ではない。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q239', 'システムの構成方式',
   '情報システムの処理形態のうち、集中処理と分散処理の一般的な特徴の組み合わせとして、適切なものはどれか。',
   NULL::text,
   '["集中処理は運用管理を一元化しやすい。分散処理は特定の1台に障害が起きても、他の機器で処理を続けやすい。", "集中処理は特定の1台に障害が起きても、他の機器で処理を続けやすい。分散処理は運用管理を一元化しやすい。", "集中処理も分散処理も、性能を高める方法は機器の台数を増やすことに限られ、設計の工夫では変わらない。", "分散処理は集中処理よりも、常に導入コストと運用の手間の両方が少ないと言い切ることができる。"]',
   0,
   '[0]',
   'single',
   '{"asked": "集中処理と分散処理は、それぞれどんな特徴を持つ処理形態なのかを問われている。", "point": "1台に処理をまとめるか、複数台に分けるかで、管理のしやすさと止まりにくさのどちらを優先するかが変わる、と対応づければ見分けられる。", "kid": "集中処理は1台のコンピュータに仕事を全部集める方式。分散処理は複数台のコンピュータに仕事を分けて任せる方式。", "eg": "集中処理は、全部の注文を1人の店長がさばく小さな店。分散処理は、複数のスタッフに担当を分けて同時に対応する店。店長が休むと集中処理の店は止まってしまうが、分散処理の店は他のスタッフが対応を続けられる。", "terms": [["集中処理", "1台の高性能なコンピュータに処理をまとめて行わせる方式"], ["分散処理", "複数台のコンピュータに処理を分けて行わせる方式"]], "think": "なぜ集中処理は管理がしやすく、分散処理は障害に強いのかがカギ。集中処理は機器が1か所にまとまっているので、設定やソフトウェアの更新を1台だけ気にすればよく、管理がしやすい。ただしその1台が止まると、処理を肩代わりする機器がないため、システム全体が止まってしまう。分散処理は複数台に処理を分けているので、管理の対象は増えるが、1台が止まっても他の機器が処理を引き継いで動き続けやすい。だから、管理のしやすさを取るか、止まりにくさを取るかという特徴の違いが生まれる。", "why_asked": "集中処理と分散処理は言葉だけ覚えると特徴を逆に結び付けてしまいやすく、組み合わせを入れ替えた誤答がよく作られる。", "vs": "分散処理はさらに水平分散処理(同じ処理を複数台で分担)と垂直分散処理(役割ごとに階層的に分ける)に分類されるが、ここではまず集中処理との対比を押さえる。", "opt": ["正解。集中処理は機器が1台にまとまるため管理がしやすく、分散処理は複数台に分かれているため一部が止まっても処理を続けやすいという、それぞれの一般的な特徴を正しく組み合わせている。", "集中処理と分散処理の特徴が入れ替わっている。管理のしやすさと止まりにくさのどちらがどちらの処理形態の特徴かを逆にしている。", "性能を高める方法は機器の台数を増やすことだけではない。1台あたりの処理能力を高める、処理の分担方法を工夫するなど、他の手段もある。", "分散処理は機器の台数が増える分、導入コストや管理の手間がかえって増えることが多く、常に少ないとは言い切れない。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"70\" y=\"16\" font-size=\"11\" fill=\"#8892a4\" text-anchor=\"middle\">集中処理</text><rect x=\"45\" y=\"30\" width=\"50\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"70\" y=\"47\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">サーバ</text><rect x=\"20\" y=\"90\" width=\"30\" height=\"20\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\"/><rect x=\"55\" y=\"90\" width=\"30\" height=\"20\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\"/><rect x=\"90\" y=\"90\" width=\"30\" height=\"20\" rx=\"3\" fill=\"none\" stroke=\"#8892a4\"/><line x1=\"35\" y1=\"90\" x2=\"65\" y2=\"56\" stroke=\"#2a2f3f\"/><line x1=\"70\" y1=\"90\" x2=\"70\" y2=\"56\" stroke=\"#2a2f3f\"/><line x1=\"105\" y1=\"90\" x2=\"75\" y2=\"56\" stroke=\"#2a2f3f\"/><text x=\"260\" y=\"16\" font-size=\"11\" fill=\"#8892a4\" text-anchor=\"middle\">分散処理</text><rect x=\"215\" y=\"60\" width=\"34\" height=\"24\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"262\" y=\"30\" width=\"34\" height=\"24\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><rect x=\"262\" y=\"95\" width=\"34\" height=\"24\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><line x1=\"249\" y1=\"66\" x2=\"262\" y2=\"42\" stroke=\"#2a2f3f\"/><line x1=\"249\" y1=\"78\" x2=\"262\" y2=\"102\" stroke=\"#2a2f3f\"/><line x1=\"279\" y1=\"54\" x2=\"279\" y2=\"95\" stroke=\"#2a2f3f\"/></svg>"}'),
  ('ap-core-q240', 'システムの構成方式',
   '分散処理はさらにいくつかの方式に分類される。同じ種類の処理を複数の対等なコンピュータに分けて並行して実行させる方式について述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["処理の負荷を複数の対等な機器で横に分け合うことから水平分散処理と呼ばれ、機器を追加することで処理能力を増やしやすい。", "処理の役割を上位の機器と下位の機器に分けて階層的に担わせる方式であり、こうした役割分担は一般に垂直分散処理と呼ばれる。", "すべての処理を1台の機器に集約し、複数の利用者から同時にアクセスさせる方式であり、これは集中処理と呼ばれる。", "処理を行う機器の台数や構成によらず、常に同じ処理時間で結果が得られることを保証する方式である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "同じ種類の処理を複数の対等な機器に分けて並行して行わせる分散処理の方式は何と呼ばれるかを問われている。", "point": "同じ処理を対等な機器どうしで横に分け合うなら水平分散処理、役割ごとに上下の階層で分けるなら垂直分散処理、と対応づければ見分けられる。", "kid": "水平分散処理は、同じ仕事を複数の機器で手分けして同時にこなす方式。", "eg": "水平分散処理は、同じ荷物の仕分け作業を複数人のスタッフが横に並んで同時にこなすイメージ。垂直分散処理は、受付・仕分け・発送というように役割を上流から下流へ分業するイメージ。", "terms": [["水平分散処理", "同じ種類の処理を対等な複数の機器に分けて並行して行わせる方式"], ["垂直分散処理", "処理の役割を階層ごとに分けて、上位と下位の機器がそれぞれ異なる役割を担う方式"]], "think": "なぜ『水平』『垂直』という呼び方になるのかがカギ。水平分散処理は、同じ立場の機器を横に並べて同じ処理を分け合うイメージなので水平と呼ばれる。垂直分散処理は、受付を担当する機器・処理を担当する機器・記録を担当する機器というように役割を上流から下流へ積み上げるイメージなので垂直と呼ばれる。呼び方は、機器どうしの関係が対等(横並び)か役割分担(上下関係)かの違いを表している。", "why_asked": "水平分散処理と垂直分散処理は名前が紛らわしく、役割の説明を入れ替えた誤答がよく作られる。", "vs": "後述のクライアントサーバシステムは、役割を分担する垂直分散処理の考え方に近い。水平分散処理とは機器どうしの関係が対等か役割分担かで区別する。", "opt": ["正解。同じ処理を対等な機器で横に分け合う方式は水平分散処理と呼ばれ、機器を増やすことで処理能力を高めやすいという特徴がある。", "これは垂直分散処理の説明である。役割を上位・下位に分ける方式であり、対等な機器で同じ処理を分け合う方式とは異なる。", "これは集中処理の説明である。複数台に処理を分ける分散処理とは反対の考え方である。", "分散処理は機器の台数や処理の分け方によって処理時間が変わり得るため、常に同じ処理時間を保証するものではない。"]}'),
  ('ap-core-q241', 'システムの構成方式',
   'システムの利用形態に関する記述のうち、バッチ処理について述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["一定量のデータや処理要求をため、決められたタイミングでまとめて処理する形態であり、給与計算や請求書発行などに用いられる。", "処理要求が発生するたびにその都度すぐさま即座に処理を行い、定められた時間内に結果を返す形態であり、工場の制御などに用いられる。", "利用者からの入力に応じてシステムが応答し、その応答を見ながら利用者が次の入力を行うことを繰り返していく形態である。", "複数の利用者が同時に更新処理を行っても、データの整合性を保ちながら一連の処理を成立させる形態である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "バッチ処理とはどのような利用形態かを問われている。", "point": "処理要求が発生するたびに1件ずつ即座に処理するのではなく、ある程度ため込んでから決まったタイミングでまとめて処理するなら、バッチ処理と判断できる。", "kid": "バッチ処理は、その場ですぐ処理せず、後でまとめて一気に処理する方式。", "eg": "バッチ処理は、洗濯物をその都度1枚ずつ洗うのではなく、ある程度たまってから洗濯機にまとめて入れて一気に洗うイメージ。", "terms": [["バッチ処理", "一定量の処理要求をため、決められたタイミングでまとめて実行する処理形態"], ["ジョブ", "バッチ処理でまとめて実行される一連の処理の単位"]], "think": "なぜまとめて処理するやり方が使われるのかがカギ。給与計算や請求書発行のように、1件ずつ即座に結果を返す必要がなく、大量のデータをまとめて処理したほうが効率がよい業務がある。処理要求のたびにシステムを都度動かすと機器の負荷が分散せずかえって非効率になる場合があるため、夜間などまとまった時間に一括して処理することで、機器を効率よく使い、日中の他の処理と衝突しないようにできる。だから、即時性より効率を優先する業務ではバッチ処理が選ばれる。", "why_asked": "バッチ処理とリアルタイム処理は対比で問われることが多く、それぞれの用途例を入れ替えた誤答が作られやすい。", "vs": "処理要求のたびに即座に結果を返す必要がある業務ではリアルタイム処理が選ばれる。まとめて処理するか、その都度即座に処理するかが分かれ目になる。", "opt": ["正解。バッチ処理は処理要求をため、決められたタイミングでまとめて処理する形態であり、即時性よりまとめて処理する効率を優先する業務に向く。", "これはリアルタイム処理の説明である。処理要求のたびに即座に処理し、時間的な制約の中で結果を返す形態であり、まとめて処理するバッチ処理とは異なる。", "これは対話型処理の説明である。利用者とシステムがやり取りしながら進める形態であり、まとめて処理するバッチ処理とは異なる。", "これはオンライントランザクション処理の説明に近い。複数の利用者の同時更新でも整合性を保つ仕組みであり、まとめて処理するバッチ処理とは異なる。"]}'),
  ('ap-core-q242', 'システムの構成方式',
   'システムの利用形態に関する記述のうち、対話型処理について述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["利用者の入力に対してシステムが応答し、その応答を見ながら利用者が次の入力を行うというやり取りを繰り返しながら処理を進める形態である。", "一定量の処理要求をため込んでおき、決められたタイミングが来るまで待ってからまとめて処理する形態である。", "処理要求が発生するたびに即座に処理を行い、定められた時間内に必ず結果を返すことを重視する形態である。", "複数の利用者が同時に更新処理を行っても、データの整合性をきちんと保ちながら一連の処理を最後まで確実にきっちり成立させ続けていく形態である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "対話型処理とはどのような利用形態かを問われている。", "point": "システムと利用者が応答を見ながら入力のやり取りを繰り返して処理を進めているなら、対話型処理と判断できる。", "kid": "対話型処理は、システムと利用者が受け答えを繰り返しながら少しずつ処理を進める方式。", "eg": "対話型処理は、店員と客が『こちらの商品でよろしいですか』『はい、それでお願いします』とやり取りしながら注文を確定していく接客のイメージ。", "terms": [["対話型処理", "利用者の入力とシステムの応答のやり取りを繰り返しながら進める処理形態"]], "think": "なぜやり取りを繰り返す形になるのかがカギ。銀行のATMや検索サイトの操作のように、利用者が次に何を入力すべきかは、その前のシステムの応答を見ないと決められない場面がある。そこで、システムが応答するたびに利用者が次の入力を選び、それをまたシステムが受け取って応答するという受け答えを繰り返すことで、あらかじめすべての手順を決めておかなくても、状況に応じて処理を進められる。だから、利用者の判断を挟みながら進めたい処理では対話型処理が使われる。", "why_asked": "対話型処理はバッチ処理・リアルタイム処理と並べて問われ、それぞれの説明を入れ替えた誤答が作られやすい。", "vs": "リアルタイム処理は時間内に結果を返すことを重視するのに対し、対話型処理は利用者との受け答えを繰り返すことを重視する点で異なる。", "opt": ["正解。対話型処理は利用者の入力とシステムの応答を繰り返しながら処理を進める形態であり、応答を見て次の入力を決めるやり取りが特徴である。", "これはバッチ処理の説明である。処理要求をため、まとめて処理する形態であり、やり取りを繰り返す対話型処理とは異なる。", "これはリアルタイム処理の説明である。時間内に結果を返すことを重視する形態であり、やり取りを繰り返す対話型処理とは異なる。", "これはオンライントランザクション処理の説明に近い。複数の利用者の同時更新でも整合性を保つ仕組みであり、やり取りを繰り返す対話型処理とは異なる。"]}'),
  ('ap-core-q243', 'システムの構成方式',
   'システムの利用形態に関する記述のうち、オンライントランザクション処理(OLTP)について述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["複数の利用者からの取引要求を同時に受け付けながら、一連の更新をひとまとまりとして扱い、整合性を保ったまま処理を成立させる形態である。", "取引要求を一定量ためておき、決められたタイミングでまとめて処理することで、即時の整合性確認を必要としない形態である。", "利用者の入力とシステムの応答を繰り返しながら、利用者の判断をそのつど挟みつつ処理を進めていく形態である。", "処理要求が発生するたびに即座に処理を行い、定められた時間内に必ず結果を返すことを最優先し、複数の利用者間の整合性は扱わない形態である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "オンライントランザクション処理(OLTP)とはどのような利用形態かを問われている。", "point": "複数の利用者からの取引要求を同時に受け付けても、一連の更新をひとまとまり(トランザクション)として扱い、整合性を保ったまま処理を成立させているなら、OLTPと判断できる。", "kid": "OLTPは、銀行のATMのように、複数人が同時に使っても口座残高などのデータがおかしくならないようにしながら取引を処理する方式。", "eg": "OLTPは、1冊しかない予約ノートに複数の窓口担当者が同時に書き込もうとしても、誰かの予約が消えたり二重に書き込まれたりしないよう、1件ずつきちんと確定させながら受け付けるイメージ。", "terms": [["トランザクション", "一連の更新処理をひとまとまりとして扱う単位。途中で中断すると更新前の状態に戻す"], ["OLTP", "オンライントランザクション処理。複数の利用者の同時アクセスでも整合性を保ちながら取引を処理する形態"]], "think": "なぜひとまとまりとして扱う必要があるのかがカギ。銀行の振込のように、出金側の残高を減らす処理と入金側の残高を増やす処理の両方が完了して初めて取引が成立する場面では、片方だけ終わって片方が失敗すると、お金が消えたり増えたりする不整合が起きる。そこで、複数の更新をひとまとまり(トランザクション)として扱い、全部完了するか、全く行われなかったことにするかのどちらかにそろえることで、複数の利用者が同時にアクセスしても整合性を保てる。だから、取引を確実に成立させたい処理ではOLTPの考え方が使われる。", "why_asked": "OLTPはバッチ処理・対話型処理と混同されやすく、『同時アクセスでも整合性を保つ』という特徴を落として問われることが多い。", "vs": "対話型処理は利用者とのやり取りの繰り返しに注目した分類だが、OLTPは複数の利用者が同時に更新しても整合性を保つという点に注目した分類であり、着目点が異なる。", "opt": ["正解。OLTPは複数の利用者からの取引要求を同時に受け付けながら、一連の更新をひとまとまりとして扱い、整合性を保ったまま処理を成立させる形態である。", "これはバッチ処理の説明である。要求をため、まとめて処理する形態であり、同時アクセスでも整合性を保つOLTPの特徴とは異なる。", "これは対話型処理の説明である。利用者とのやり取りを繰り返す形態であり、複数の利用者間の整合性を保つOLTPの特徴とは異なる。", "整合性を扱わないとしている点が誤り。OLTPは即時性だけでなく、複数の利用者間のデータの整合性を保つことも重視する。"]}'),
  ('ap-core-q244', 'システムの構成方式',
   'クライアントサーバシステムの考え方について述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["サービスを要求する側(クライアント)と、サービスを提供する側(サーバ)に役割を分け、クライアントからの要求に応じてサーバが処理結果を返す方式である。", "すべての処理を1台の機器に集約し、利用者の端末はあくまで処理結果を画面に表示するだけの役割しか持たず、入力の作成以外の処理は一切行わない方式である。", "複数の対等な機器が同じ種類の処理を分担し、役割の違いを設けずに並行して処理を進めていく方式であり、機器どうしは対等な関係にある。", "一定量の処理要求をあらかじめため込んでおき、決められたタイミングでまとめてサーバ側が処理する方式であり、即時の応答は行わない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "クライアントサーバシステムの考え方はどのようなものかを問われている。", "point": "サービスを求める側と提供する側で役割を分け、求める側からの要求に応じて提供する側が処理して返しているなら、クライアントサーバシステムと判断できる。", "kid": "クライアントサーバシステムは、お願いする側(クライアント)とお願いされて処理する側(サーバ)に役割を分ける仕組み。", "eg": "クライアントサーバシステムは、レストランで客(クライアント)が注文し、厨房(サーバ)が調理して提供するイメージ。客は調理せず注文するだけ、厨房は注文を受けてから調理する。", "terms": [["クライアント", "サービスを要求する側の機器やソフトウェア"], ["サーバ", "要求に応じてサービスを提供する側の機器やソフトウェア"]], "think": "なぜ役割を分けるのかがカギ。すべての機器に同じ機能を持たせると、データを更新するたびに全部の機器で同じ作業をそろえる必要があり、管理が煩雑になる。そこで、データの管理や処理をサーバ側にまとめ、クライアント側は要求を送って結果を受け取ることに専念させることで、データの管理場所を一本化しつつ、多くのクライアントから同じサーバへ要求できるようになる。だから、役割を分けることで管理のしやすさと利用のしやすさを両立できる。", "why_asked": "クライアントサーバシステムは後述のシンクライアントシステムと混同されやすく、役割分担の程度の違いが問われる。", "vs": "垂直分散処理(役割を階層的に分ける分散処理)の考え方に近いが、クライアントサーバシステムは特に『要求する側』と『提供する側』という2つの役割に注目した呼び方である。", "opt": ["正解。クライアントサーバシステムは、サービスを要求するクライアントと、要求に応じて処理し結果を返すサーバに役割を分ける方式である。", "端末側が表示専用で処理を持たない、より役割分担が徹底した方式(後述のシンクライアントシステム)に近い説明であり、クライアントサーバシステム一般の説明とは異なる。", "これは水平分散処理の説明である。対等な機器が同じ処理を分担する方式であり、役割を分けるクライアントサーバシステムとは異なる。", "これはバッチ処理の説明である。処理要求をため、まとめて処理するタイミングに注目した分類であり、役割分担に注目したクライアントサーバシステムとは異なる。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"20\" y=\"55\" width=\"90\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"65\" y=\"79\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">クライアント</text><rect x=\"230\" y=\"55\" width=\"90\" height=\"40\" rx=\"6\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"275\" y=\"79\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">サーバ</text><line x1=\"110\" y1=\"65\" x2=\"228\" y2=\"65\" stroke=\"#8892a4\"/><text x=\"170\" y=\"58\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\">要求</text><line x1=\"228\" y1=\"85\" x2=\"110\" y2=\"85\" stroke=\"#8892a4\"/><text x=\"170\" y=\"102\" font-size=\"10\" fill=\"#8892a4\" text-anchor=\"middle\">応答</text></svg>"}'),
  ('ap-core-q245', 'システムの構成方式',
   'Webシステムの考え方について述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["利用者側はWebブラウザをクライアントとして用い、Webサーバに要求を送って結果を受け取る、クライアントサーバシステムの一形態である。", "利用者側の端末には表示や入力の機能さえ一切持たせず、すべての処理をサーバ側の機器だけで完結させる方式である。", "複数の対等なWebサーバが同じ種類の処理を分担し、役割の違いを設けずに並行して処理を進めていく方式である。", "クライアントサーバシステムとは根本的に異なる考え方であり、サーバをまったく介さずに利用者どうしの端末が直接データをやり取りする方式である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "Webシステムはどのような考え方に基づく仕組みかを問われている。", "point": "利用者側がWebブラウザを使ってサーバへ要求を送り、結果を受け取っているなら、クライアントサーバシステムの一種としてのWebシステムと判断できる。", "kid": "Webシステムは、専用のクライアントソフトの代わりにWebブラウザをクライアントとして使うクライアントサーバシステム。", "eg": "Webシステムは、専用の注文用紙(専用クライアントソフト)を使わずに、共通のメモ用紙(Webブラウザ)を使ってどの店(Webサーバ)にも注文できるようにしたイメージ。", "terms": [["Webブラウザ", "Webシステムにおいてクライアントの役割を担うソフトウェア"], ["Webサーバ", "Webブラウザからの要求を受けてWebページなどを返すサーバ"]], "think": "なぜWebブラウザを使う形になったのかがカギ。クライアントサーバシステムでは、利用するサービスごとに専用のクライアントソフトを端末にインストールする必要があると、サービスが増えるたびに端末の準備が大変になる。そこで、共通のクライアントソフトとしてWebブラウザを使い、要求先のサーバ(Webサーバ)を切り替えるだけで様々なサービスを利用できるようにした。だから、Webシステムはクライアントサーバシステムの役割分担を保ちながら、クライアント側の準備の手間を減らす仕組みだと言える。", "why_asked": "WebシステムはWebブラウザを使う点だけが強調され、クライアントサーバシステムの一形態であるという位置づけが見落とされやすい。", "vs": "クライアントサーバシステム一般は専用のクライアントソフトを使うこともあるが、Webシステムは共通のWebブラウザをクライアントとして使う点で区別できる。", "opt": ["正解。WebシステムはWebブラウザをクライアントとして用い、Webサーバへ要求を送って結果を受け取る、クライアントサーバシステムの一形態である。", "端末側が表示専用で処理を持たない、より役割分担が徹底した方式(シンクライアントシステム)に近い説明であり、Webシステム一般の説明とは異なる。", "これは水平分散処理の説明である。対等な機器が同じ処理を分担する方式であり、役割を分けるWebシステムとは異なる。", "Webシステムはサーバを介してブラウザから要求を送る仕組みであり、サーバを介さず端末どうしが直接やり取りする方式ではない。"]}'),
  ('ap-core-q246', 'システムの構成方式',
   'シンクライアントシステムについて述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["利用者の端末側には画面表示や入力といった最小限の機能だけを持たせ、データの処理や保存の大部分をサーバ側に集約させる方式である。", "利用者の端末側に主要なアプリケーションやデータの大部分を保持させ、サーバ側にはあえてごく最小限の機能しか持たせない方式である。", "複数の対等な端末が同じ種類の処理を分担し、サーバを介さずに直接データをやり取りする方式である。", "処理要求を一定量ため込んでおき、決められたタイミングでまとめて端末側だけで処理する方式である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "シンクライアントシステムとはどのような方式かを問われている。", "point": "端末側は画面表示や入力といった最小限の機能しか持たず、処理やデータ保存の大部分をサーバ側に集約しているなら、シンクライアントシステムと判断できる。", "kid": "シンクライアントシステムは、手元の端末にはできるだけ機能を持たせず、頭脳にあたる処理やデータをサーバ側にまとめておく方式。", "eg": "シンクライアントは、手元の端末が画面と入力だけを担当するモニターとキーボードのようなもので、実際に考えて処理する頭脳の部分はサーバ側に置いてあるイメージ。", "terms": [["シンクライアント", "処理やデータをサーバ側に集約し、端末側の機能を最小限にとどめる方式"]], "think": "なぜ端末側の機能をあえて減らすのかがカギ。通常のクライアントサーバシステムでは、クライアント側の端末にもアプリケーションやデータの一部を持たせることが多いが、そうすると端末が紛失・盗難にあった際にデータが外部に漏れる恐れがあり、また端末ごとにソフトウェアを更新する手間もかかる。そこで、処理やデータをサーバ側に集約し、端末側は画面表示と入力だけに限定することで、端末にデータを残さず情報漏洩のリスクを減らし、更新もサーバ側だけで済ませられるようにする。だから、シンクライアントシステムは端末を軽くすることで安全性と管理のしやすさを高める考え方だと言える。", "why_asked": "シンクライアントはクライアントサーバシステム一般と混同されやすく、端末側の機能をどこまで減らすかという程度の違いが問われる。", "vs": "クライアントサーバシステム一般は端末側にもアプリケーションやデータを持たせることがあるが、シンクライアントシステムは端末側の機能を最小限に絞る点で区別される。", "opt": ["正解。シンクライアントシステムは端末側の機能を画面表示や入力といった最小限にとどめ、処理やデータ保存をサーバ側に集約する方式である。", "端末側とサーバ側の役割が逆になっている。シンクライアントシステムは端末側の機能を減らし、サーバ側に処理やデータを集約する方式である。", "これは水平分散処理の説明である。対等な機器が同じ処理を分担する方式であり、端末側の機能を減らすシンクライアントシステムとは異なる。", "これはバッチ処理の説明に近いが、処理を行う場所が端末側になっている点も誤り。シンクライアントシステムでは処理はサーバ側に集約される。"]}'),
  ('ap-core-q247', 'システムの構成方式',
   '組織がシンクライアントシステムを採用する狙いとして、最も適切なものはどれか。',
   NULL::text,
   '["端末側にデータを残さないようにすることで、端末の紛失や盗難による情報漏洩のリスクを減らし、管理もサーバ側でまとめて行えるようにするため。", "端末側の処理性能をあえて大幅に高めることで、サーバ側の負荷を減らし、通信が途中で切れても端末単独で全ての処理を続けられるようにするため。", "複数の対等な端末に処理を分担させることで、1台あたりの処理量を減らし、全体の処理速度を高めるようにするため。", "処理要求を一定量ためてからまとめて処理することで、サーバ側の負荷が集中する時間帯そのものを減らすため。"]',
   0,
   '[0]',
   'single',
   '{"asked": "組織がシンクライアントシステムを採用する狙いは何かを問われている。", "point": "端末にデータを残さないことによる情報漏洩リスクの低減と、管理をサーバ側にまとめられることの2点が狙いだと押さえれば見分けられる。", "kid": "シンクライアントを使う狙いは、端末を軽くすることで、情報が漏れにくくなり、管理も楽になること。", "eg": "会社の重要書類を、社員が各自の机の引き出し(端末)に置くのではなく、鍵のかかる書庫(サーバ)にまとめて保管し、社員は書庫から必要な分だけ見に行くようにするイメージ。引き出しごと盗まれる心配がなくなる。", "terms": [["情報漏洩", "本来アクセスできない人にデータが渡ってしまうこと"]], "think": "なぜシンクライアントを使うのかがカギ。端末側にデータやアプリケーションを持たせていると、端末を紛失したり盗まれたりしたときに、その中のデータがそのまま外部に渡ってしまう恐れがある。また、端末が増えるほど、1台ずつソフトウェアを更新したり設定を管理したりする手間も増えていく。そこで端末側にはデータを残さずサーバ側にまとめておくことで、端末を紛失してもサーバ側のデータそのものは漏れず、更新や設定もサーバ側で一括して行えるようになる。だから、シンクライアントは情報漏洩リスクを減らすことと管理の手間を減らすことの両方を狙って採用される。", "why_asked": "シンクライアントの利点は『処理が軽い』という誤った理解で問われやすいが、実際の狙いは情報漏洩対策と管理の一元化にある。", "vs": "端末側の処理性能を高める方向はシンクライアントの狙いとは逆方向であり、混同しないよう注意する。", "opt": ["正解。シンクライアントシステムは端末側にデータを残さないことで情報漏洩のリスクを減らし、更新などの管理をサーバ側でまとめて行えるようにする狙いで採用される。", "端末側の処理性能を高める方向はシンクライアントの狙いとは逆であり、シンクライアントは端末側の機能をむしろ最小限にとどめる考え方である。", "これは水平分散処理を採用する狙いに近い説明であり、端末にデータを残さないことを狙うシンクライアントの説明とは異なる。", "これはバッチ処理を採用する狙いに近い説明であり、端末にデータを残さないことを狙うシンクライアントの説明とは異なる。"]}'),
  ('ap-core-q248', 'システムの構成方式',
   'フォールトトレラントシステムの設計思想について述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["システムを構成する機器の一部に故障が起きても、予備の機器や仕組みに切り替えることで、システム全体の機能を止めずに動かし続けようとする考え方である。", "システムを構成する機器の数を可能な限り減らすことで、故障そのものが起きる確率をできるだけ小さくしようとする考え方である。", "故障が起きたことを検知したら、その原因をきちんと突き止めて完全に直すまでの間、システム全体をいったん安全に停止させることを最優先する考え方である。", "システムの処理性能を最大限に高めることを目的とし、故障への備えよりも処理速度を優先しようとする考え方である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "フォールトトレラントシステムはどのような設計思想に基づいているかを問われている。", "point": "機器の一部が故障しても、予備の仕組みに切り替えてシステム全体の機能を止めないようにしているなら、フォールトトレラントシステムの考え方だと判断できる。", "kid": "フォールトトレラントシステムは、一部が壊れてもシステム全体は止めないように作る考え方。", "eg": "フォールトトレラントシステムは、飛行機のエンジンが複数あるのと同じ考え方。1つのエンジンが止まっても、残りのエンジンで飛行を続けられるようにしてある。", "terms": [["フォールト(故障)", "システムを構成する機器やソフトウェアに生じる不具合"], ["冗長構成", "故障に備えて予備の機器や経路をあらかじめ用意しておく構成"]], "think": "なぜ止めない設計が必要なのかがカギ。銀行のシステムや航空管制のように、一瞬でも止まると大きな影響が出るシステムでは、故障が起きた後に直すまで止めてよいという前提が成り立たない。そこで、あらかじめ予備の機器や経路を用意しておき(冗長構成)、一部が故障したことを検知したら自動的に予備側へ切り替えることで、利用者から見ると機能が止まっていないように動かし続けられる。だから、フォールトトレラントシステムは『故障を起こさないこと』ではなく『故障が起きてもシステム全体は止めないこと』を目指す設計思想だと言える。", "why_asked": "フォールトトレラントは『故障を防ぐ』設計だと誤解されやすいが、実際は『故障が起きても止めない』設計思想である点が問われる。", "vs": "個々の機器の稼働率を高めて故障そのものを減らす取り組みとは別に、フォールトトレラントシステムは故障が起きた後もシステム全体を止めないための設計思想という点で区別される。", "opt": ["正解。フォールトトレラントシステムは、機器の一部に故障が起きても予備の機器や仕組みに切り替え、システム全体の機能を止めずに動かし続けようとする設計思想である。", "機器を減らして故障の確率そのものを下げる考え方であり、故障が起きた後もシステム全体を止めずに動かし続けようとするフォールトトレラントシステムの考え方とは異なる。", "故障が起きたら安全のため停止を優先する考え方であり、故障が起きてもシステム全体を止めずに動かし続けようとするフォールトトレラントシステムの考え方とは異なる。", "処理速度を優先し故障への備えを後回しにする考え方であり、故障への備えを重視するフォールトトレラントシステムの考え方とは異なる。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"18\" font-size=\"11\" fill=\"#8892a4\" text-anchor=\"middle\">冗長構成</text><rect x=\"15\" y=\"60\" width=\"55\" height=\"30\" rx=\"5\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"42\" y=\"79\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">入力</text><rect x=\"135\" y=\"28\" width=\"80\" height=\"30\" rx=\"5\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.5\"/><text x=\"175\" y=\"47\" font-size=\"10\" fill=\"#c47070\" text-anchor=\"middle\">機器A(故障)</text><rect x=\"135\" y=\"92\" width=\"80\" height=\"30\" rx=\"5\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><text x=\"175\" y=\"111\" font-size=\"10\" fill=\"#6ab08d\" text-anchor=\"middle\">機器B(稼働)</text><rect x=\"270\" y=\"60\" width=\"55\" height=\"30\" rx=\"5\" fill=\"none\" stroke=\"#8892a4\"/><text x=\"297\" y=\"79\" font-size=\"10\" fill=\"#e8eaf0\" text-anchor=\"middle\">出力</text><line x1=\"70\" y1=\"70\" x2=\"135\" y2=\"45\" stroke=\"#2a2f3f\"/><line x1=\"70\" y1=\"80\" x2=\"135\" y2=\"105\" stroke=\"#2a2f3f\"/><line x1=\"215\" y1=\"107\" x2=\"270\" y2=\"80\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/></svg>"}'),
  ('ap-core-q249', 'システムの構成方式',
   'HPC(ハイパフォーマンスコンピューティング)の概念について述べたものとして、最も適切なものはどれか。',
   NULL::text,
   '["気象予測やシミュレーションのように大量の計算を要する処理を、多数の演算資源を組み合わせて高速に処理できるようにする構成の考え方である。", "端末側の機能をあえて最小限にとどめ、処理やデータをサーバ側に集約することで、情報漏洩のリスクを減らす構成の考え方である。", "機器の一部に故障が起きても、予備の仕組みに切り替えることでシステム全体の機能を止めずに動かし続ける構成の考え方である。", "処理要求を一定量ためておき、あらかじめ決められたタイミングでまとめて処理することで、機器を効率よく使えるようにする構成の考え方である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "HPC(ハイパフォーマンスコンピューティング)とはどのような構成の考え方かを問われている。", "point": "気象予測やシミュレーションのような大量の計算を、多数の演算資源を組み合わせて高速に処理しようとしているなら、HPCの考え方だと判断できる。", "kid": "HPCは、ものすごく大量の計算を、たくさんの計算機を組み合わせて速く終わらせるための構成の考え方。", "eg": "HPCは、1人では何年もかかる大量の計算問題を、大勢の人を集めて同時に手分けして解かせ、短時間で終わらせるイメージ。", "terms": [["HPC", "ハイパフォーマンスコンピューティング。大量の計算処理を多数の演算資源を組み合わせて高速に行う構成の考え方"], ["クラスタ", "HPCなどで複数の計算機をまとめて1つの計算資源として扱う構成"]], "think": "なぜ多数の演算資源を組み合わせるのかがカギ。気象予測やシミュレーションのような計算は、1台の計算機の性能をどれだけ上げても、現実的な時間内に終わらせるには限界がある。そこで、多数の計算機を組み合わせて同時に計算を分担させることで、1台では到底終わらない量の計算を、現実的な時間内に終わらせられるようにする。だから、HPCは処理をどう役割分担するかというより、大量の計算そのものを高速化することに焦点を当てた構成の考え方だと言える。", "why_asked": "HPCは分散処理の一種と混同され、他の構成方式(シンクライアントやフォールトトレラント)の説明と入れ替えた誤答が作られやすい。", "vs": "分散処理は役割や負荷の分け方に注目した分類だが、HPCは大量の計算を高速に終わらせるという目的に注目した分類であり、着目点が異なる。", "opt": ["正解。HPCは気象予測やシミュレーションのような大量の計算を要する処理を、多数の演算資源を組み合わせて高速に処理できるようにする構成の考え方である。", "これはシンクライアントシステムの説明である。端末側の機能を減らし情報漏洩を防ぐ狙いの構成であり、大量の計算を高速化するHPCの説明とは異なる。", "これはフォールトトレラントシステムの説明である。故障が起きてもシステムを止めない構成であり、大量の計算を高速化するHPCの説明とは異なる。", "これはバッチ処理の説明である。処理をため込みまとめて処理するタイミングに注目した考え方であり、大量の計算を高速化するHPCの説明とは異なる。"]}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
